  // Write your code here
  return {};
}

solution:
function parseQueryString(query) {
  if (!query) return {};
  const q = query.startsWith('?') ? query.slice(1) : query;
  if (!q) return {};
  return q.split('&').reduce((acc, part) => {
    const [k, v] = part.split('=');
    if (k) acc[decodeURIComponent(k)] = decodeURIComponent(v || '');
    return acc;
  }, {});
}

testSuite:
expect(parseQueryString("?name=alice&age=25")).to.deep.equal({ name: "alice", age: "25" });
expect(parseQueryString("search=code&page=1&sort=desc")).to.deep.equal({ search: "code", page: "1", sort: "desc" });
expect(parseQueryString("")).to.deep.equal({});

